CREATE TABLE Country
(
    Code        VARCHAR(4)  NOT NULL,
    Name        VARCHAR(50),
    Capital     VARCHAR(50),
    Province    VARCHAR(50),
    Area        FLOAT,
    Population  FLOAT,

    CONSTRAINT PK_Country PRIMARY KEY (Code),
    CONSTRAINT UQ_Country_Name UNIQUE (Name),
    CONSTRAINT CK_Country_Area CHECK (Area >= 0),
    CONSTRAINT CK_Country_Population CHECK (Population >= 0)
);
GO

CREATE TABLE Continent
(
    Name  VARCHAR(20)   NOT NULL,
    Area  NUMERIC(10,0),

    CONSTRAINT PK_Continent PRIMARY KEY (Name)
);
GO

CREATE TABLE Mountain
(
    Name       VARCHAR(50) NOT NULL,
    Mountains  VARCHAR(50),
    Elevation  FLOAT,
    Type       VARCHAR(10),
    Latitude   FLOAT,
    Longitude  FLOAT,

    CONSTRAINT PK_Mountain PRIMARY KEY (Name),
    CONSTRAINT CK_Mountain_Coord CHECK ((Latitude >= -90) AND (Latitude <= 90) AND (Longitude > -180) AND (Longitude <= 180))
);
GO

CREATE TABLE Desert
(
    Name       VARCHAR(50) NOT NULL,
    Area       FLOAT,
    Latitude   FLOAT,
    Longitude  FLOAT,

    CONSTRAINT PK_Desert PRIMARY KEY (Name),
    CONSTRAINT CK_Desert_Coord CHECK ((Latitude >= -90) AND (Latitude <= 90) AND (Longitude > -180) AND (Longitude <= 180))
);
GO

CREATE TABLE Island
(
    Name       VARCHAR(50) NOT NULL,
    Islands    VARCHAR(50),
    Area       FLOAT,
    Elevation  FLOAT,
    Type       VARCHAR(15),
    Latitude   FLOAT,
    Longitude  FLOAT,

    CONSTRAINT PK_Island PRIMARY KEY (Name),
    CONSTRAINT CK_Island_Area CHECK (Area >= 0),
    CONSTRAINT CK_Island_Coord CHECK ((Latitude >= -90) AND (Latitude <= 90) AND (Longitude > -180) AND (Longitude <= 180))
);
GO

CREATE TABLE Sea
(
    Name   VARCHAR(50) NOT NULL,
    Area   FLOAT,
    Depth  FLOAT,

    CONSTRAINT PK_Sea PRIMARY KEY (Name),
    CONSTRAINT CK_Sea_Area CHECK (Area >= 0),
    CONSTRAINT CK_Sea_Depth CHECK (Depth >= 0)
);
GO

CREATE TABLE Lake
(
    Name       VARCHAR(50) NOT NULL,
    River      VARCHAR(50),
    Area       FLOAT,
    Elevation  FLOAT,
    Depth      FLOAT,
    Height     FLOAT,
    Type       VARCHAR(12),
    Latitude   FLOAT,
    Longitude  FLOAT,

    CONSTRAINT PK_Lake PRIMARY KEY (Name),
    CONSTRAINT CK_Lake_Area CHECK (Area >= 0),
    CONSTRAINT CK_Lake_Depth CHECK (Depth >= 0),
    CONSTRAINT CK_Lake_Height CHECK (Height > 0),
    CONSTRAINT CK_Lake_Coord CHECK ((Latitude >= -90) AND (Latitude <= 90) AND (Longitude > -180) AND (Longitude <= 180))
);
GO

CREATE TABLE Sublanguage
(
    Sublang  VARCHAR(50) NOT NULL,
    Suplang  VARCHAR(50),

    CONSTRAINT PK_Sublanguage PRIMARY KEY (Sublang)
);
GO

CREATE TABLE Province
(
    Name        VARCHAR(50) NOT NULL,
    Country     VARCHAR(4)  NOT NULL,
    Population  FLOAT,
    Area        FLOAT,
    Capital     VARCHAR(50),
    CapProv     VARCHAR(50),

    CONSTRAINT PK_Province PRIMARY KEY (Name, Country),
    CONSTRAINT CK_Province_Population CHECK (Population >= 0),
    CONSTRAINT CK_Province_Area CHECK (Area >= 0),
    CONSTRAINT FK_Province_Country FOREIGN KEY (Country) REFERENCES Country (Code)
);
GO

CREATE TABLE City
(
    Name        VARCHAR(50) NOT NULL,
    Country     VARCHAR(4)  NOT NULL,
    Province    VARCHAR(50) NOT NULL,
    Population  FLOAT,
    Latitude    FLOAT,
    Longitude   FLOAT,
    Elevation   FLOAT,

    CONSTRAINT PK_City PRIMARY KEY (Name, Country, Province),
    CONSTRAINT CK_City_Population CHECK (Population >= 0),
    CONSTRAINT CK_City_Latitude CHECK ((Latitude >= -90) AND (Latitude <= 90)),
    CONSTRAINT CK_City_Longitude CHECK ((Longitude >= -180) AND (Longitude <= 180)),
    CONSTRAINT FK_City_Country FOREIGN KEY (Country) REFERENCES Country (Code),
    CONSTRAINT FK_City_Province FOREIGN KEY (Province, Country) REFERENCES Province (Name, Country)
);
GO

CREATE TABLE Economy
(
    Country       VARCHAR(4) NOT NULL,
    GDP           FLOAT,
    Agriculture   FLOAT,
    Service       FLOAT,
    Industry      FLOAT,
    Inflation     FLOAT,
    Unemployment  FLOAT,

    CONSTRAINT PK_Economy PRIMARY KEY (Country),
    CONSTRAINT CK_Economy_GDP CHECK (GDP >= 0),
    CONSTRAINT FK_Economy_Country FOREIGN KEY (Country) REFERENCES Country (Code)
);
GO

CREATE TABLE Population
(
    Country            VARCHAR(4) NOT NULL,
    Population_Growth  FLOAT,
    Infant_Mortality   FLOAT,

    CONSTRAINT PK_Population PRIMARY KEY (Country),
    CONSTRAINT FK_Population_Country FOREIGN KEY (Country) REFERENCES Country (Code)
);
GO

CREATE TABLE Politics
(
    Country       VARCHAR(4)   NOT NULL,
    Independence  DATE,
    WasDependent  VARCHAR(50),
    Dependent     VARCHAR(4),
    Government    VARCHAR(120),

    CONSTRAINT PK_Politics PRIMARY KEY (Country),
    CONSTRAINT FK_Politics_Country FOREIGN KEY (Country) REFERENCES Country (Code),
    CONSTRAINT FK_Politics_Dependent FOREIGN KEY (Dependent) REFERENCES Country (Code)
);
GO

CREATE TABLE Religion
(
    Name        VARCHAR(50) NOT NULL,
    Country     VARCHAR(4)  NOT NULL,
    Percentage  FLOAT,

    CONSTRAINT PK_Religion PRIMARY KEY (Name, Country),
    CONSTRAINT CK_Religion_Percentage CHECK ((Percentage > 0) AND (Percentage <= 100)),
    CONSTRAINT FK_Religion_Country FOREIGN KEY (Country) REFERENCES Country (Code)
);
GO

CREATE TABLE EthnicGroup
(
    Name        VARCHAR(50) NOT NULL,
    Country     VARCHAR(4)  NOT NULL,
    Percentage  FLOAT,

    CONSTRAINT PK_EthnicGroup PRIMARY KEY (Name, Country),
    CONSTRAINT CK_EthnicGroup_Percentage CHECK ((Percentage > 0) AND (Percentage <= 100)),
    CONSTRAINT FK_EthnicGroup_Country FOREIGN KEY (Country) REFERENCES Country (Code)
);
GO

CREATE TABLE Language
(
    Name        VARCHAR(50) NOT NULL,
    Country     VARCHAR(4)  NOT NULL,
    Percentage  FLOAT,

    CONSTRAINT PK_Language PRIMARY KEY (Name, Country),
    CONSTRAINT CK_Language_Percentage CHECK ((Percentage > 0) AND (Percentage <= 100)),
    CONSTRAINT FK_Language_Country FOREIGN KEY (Country) REFERENCES Country (Code)
);
GO

CREATE TABLE Countrypops
(
    Country     VARCHAR(4) NOT NULL,
    Year        FLOAT      NOT NULL,
    Population  FLOAT,

    CONSTRAINT PK_Countrypops PRIMARY KEY (Country, Year),
    CONSTRAINT CK_Countrypops_Year CHECK (Year >= 0),
    CONSTRAINT CK_Countrypops_Population CHECK (Population >= 0),
    CONSTRAINT FK_Countrypops_Country FOREIGN KEY (Country) REFERENCES Country (Code)
);
GO

CREATE TABLE Countryothername
(
    Country    VARCHAR(4)  NOT NULL,
    othername  VARCHAR(50) NOT NULL,

    CONSTRAINT PK_Countryothername PRIMARY KEY (Country, othername),
    CONSTRAINT FK_Countryothername_Country FOREIGN KEY (Country) REFERENCES Country (Code)
