GO

CREATE TABLE Provpops
(
    Country     VARCHAR(4)  NOT NULL,
    Province    VARCHAR(50) NOT NULL,
    Year        FLOAT       NOT NULL,
    Population  FLOAT,

    CONSTRAINT PK_Provpops PRIMARY KEY (Country, Province, Year),
    CONSTRAINT CK_Provpops_Year CHECK (Year >= 0),
    CONSTRAINT CK_Provpops_Population CHECK (Population >= 0),
    CONSTRAINT FK_Provpops_Province FOREIGN KEY (Province, Country) REFERENCES Province (Name, Country)
);
