CREATE TABLE Provinceothername
(
    Country    VARCHAR(4)  NOT NULL,
    Province   VARCHAR(50) NOT NULL,
    othername  VARCHAR(50) NOT NULL,

    CONSTRAINT PK_Provinceothername PRIMARY KEY (Country, Province, othername),
    CONSTRAINT FK_Provinceothername_Province FOREIGN KEY (Province, Country) REFERENCES Province (Name, Country)
);
GO

CREATE TABLE Provincelocalname
(
    Country    VARCHAR(4)   NOT NULL,
    Province   VARCHAR(50)  NOT NULL,
    localname  VARCHAR(300),

    CONSTRAINT PK_Provincelocalname PRIMARY KEY (Country, Province),
    CONSTRAINT FK_Provincelocalname_Province FOREIGN KEY (Province, Country) REFERENCES Province (Name, Country)
);
GO

CREATE TABLE Citypops
(
    Country     VARCHAR(4)  NOT NULL,
    Province    VARCHAR(50) NOT NULL,
    City        VARCHAR(50) NOT NULL,
    Year        FLOAT       NOT NULL,
    Population  FLOAT,

    CONSTRAINT PK_Citypops PRIMARY KEY (Country, Province, City, Year),
    CONSTRAINT CK_Citypops_Year CHECK (Year >= 0),
    CONSTRAINT CK_Citypops_Population CHECK (Population >= 0),
    CONSTRAINT FK_Citypops_City FOREIGN KEY (City, Country, Province) REFERENCES City (Name, Country, Province)
