CREATE TABLE Cityothername
(
    Country    VARCHAR(4)  NOT NULL,
    Province   VARCHAR(50) NOT NULL,
    City       VARCHAR(50) NOT NULL,
    othername  VARCHAR(50) NOT NULL,

    CONSTRAINT PK_Cityothername PRIMARY KEY (Country, Province, City, othername),
    CONSTRAINT FK_Cityothername_City FOREIGN KEY (City, Country, Province) REFERENCES City (Name, Country, Province)
