CREATE TABLE Citylocalname
(
    Country    VARCHAR(4)   NOT NULL,
    Province   VARCHAR(50)  NOT NULL,
    City       VARCHAR(50)  NOT NULL,
    localname  VARCHAR(300),

    CONSTRAINT PK_Citylocalname PRIMARY KEY (Country, Province, City),
    CONSTRAINT FK_Citylocalname_City FOREIGN KEY (City, Country, Province) REFERENCES City (Name, Country, Province)
