CREATE TABLE borders
(
    Country1  VARCHAR(4) NOT NULL,
    Country2  VARCHAR(4) NOT NULL,
    Length    FLOAT,

    CONSTRAINT PK_borders PRIMARY KEY (Country1, Country2),
    CONSTRAINT CK_borders_Length CHECK (Length > 0),
    CONSTRAINT FK_borders_Country1 FOREIGN KEY (Country1) REFERENCES Country (Code),
    CONSTRAINT FK_borders_Country2 FOREIGN KEY (Country2) REFERENCES Country (Code)
);
