GO

CREATE TABLE Organization
(
    Abbreviation  VARCHAR(12)  NOT NULL,
    Name          VARCHAR(100),
    City          VARCHAR(50),
    Country       VARCHAR(4),
    Province      VARCHAR(50),
    Established   DATE,

    CONSTRAINT PK_Organization PRIMARY KEY (Abbreviation),
    CONSTRAINT UQ_Organization_Name UNIQUE (Name),
    CONSTRAINT FK_Organization_Country FOREIGN KEY (Country) REFERENCES Country (Code),
    CONSTRAINT FK_Organization_City FOREIGN KEY (City, Country, Province) REFERENCES City (Name, Country, Province)
);
GO

CREATE TABLE isMember
(
    Country       VARCHAR(4)  NOT NULL,
    Organization  VARCHAR(12) NOT NULL,
    Type          VARCHAR(60),

    CONSTRAINT PK_isMember PRIMARY KEY (Country, Organization),
    CONSTRAINT FK_isMember_Country FOREIGN KEY (Country) REFERENCES Country (Code),
    CONSTRAINT FK_isMember_Organization FOREIGN KEY (Organization) REFERENCES Organization (Abbreviation)
);
GO

CREATE TABLE River
(
    Name              VARCHAR(50) NOT NULL,
    River             VARCHAR(50),
    Lake              VARCHAR(50),
    Sea               VARCHAR(50),
    Length            FLOAT,
    Area              FLOAT,
    SourceLatitude    FLOAT,
    SourceLongitude   FLOAT,
    Mountains         VARCHAR(50),
    SourceElevation   FLOAT,
    EstuaryLatitude   FLOAT,
    EstuaryLongitude  FLOAT,
    EstuaryElevation  FLOAT,

    CONSTRAINT PK_River PRIMARY KEY (Name),
    CONSTRAINT CK_River_Length CHECK (Length >= 0),
    CONSTRAINT CK_River_Area CHECK (Area >= 0),
    CONSTRAINT CK_River_SourceCoord CHECK ((SourceLatitude >= -90) AND (SourceLatitude <= 90) AND (SourceLongitude > -180) AND (SourceLongitude <= 180)),
    CONSTRAINT CK_River_EstuaryCoord CHECK ((EstuaryLatitude >= -90) AND (EstuaryLatitude <= 90) AND (EstuaryLongitude > -180) AND (EstuaryLongitude <= 180)),
    CONSTRAINT CK_River_FlowsInto CHECK (NOT (River IS NOT NULL AND Sea IS NOT NULL)),
    CONSTRAINT FK_River_River FOREIGN KEY (River) REFERENCES River (Name),
    CONSTRAINT FK_River_Lake FOREIGN KEY (Lake) REFERENCES Lake (Name),
    CONSTRAINT FK_River_Sea FOREIGN KEY (Sea) REFERENCES Sea (Name)
);
GO

CREATE TABLE RiverThrough
(
    River  VARCHAR(50) NOT NULL,
    Lake   VARCHAR(50) NOT NULL,

    CONSTRAINT PK_RiverThrough PRIMARY KEY (River, Lake),
    CONSTRAINT FK_RiverThrough_River FOREIGN KEY (River) REFERENCES River (Name),
    CONSTRAINT FK_RiverThrough_Lake FOREIGN KEY (Lake) REFERENCES Lake (Name)
);
GO

