    CONSTRAINT FK_geoDesert_Province FOREIGN KEY (Province, Country) REFERENCES Province (Name, Country),
    CONSTRAINT FK_geoDesert_Desert FOREIGN KEY (Desert) REFERENCES Desert (Name)
