    CONSTRAINT FK_geoLake_Lake FOREIGN KEY (Lake) REFERENCES Lake (Name)
);
GO

CREATE TABLE geo_Source
(
    Province  VARCHAR(50) NOT NULL,
    Country   VARCHAR(4)  NOT NULL,
    River     VARCHAR(50) NOT NULL,

    CONSTRAINT PK_geo_Source PRIMARY KEY (Province, Country, River),
    CONSTRAINT FK_geoSource_Province FOREIGN KEY (Province, Country) REFERENCES Province (Name, Country),
    CONSTRAINT FK_geoSource_River FOREIGN KEY (River) REFERENCES River (Name)
);
GO

