    CONSTRAINT PK_geo_Estuary PRIMARY KEY (Province, Country, River),
    CONSTRAINT FK_geoEstuary_Province FOREIGN KEY (Province, Country) REFERENCES Province (Name, Country),
    CONSTRAINT FK_geoEstuary_River FOREIGN KEY (River) REFERENCES River (Name)
