    CONSTRAINT FK_Airport_Country FOREIGN KEY (Country) REFERENCES Country (Code),
    CONSTRAINT FK_Airport_City FOREIGN KEY (City, Country, Province) REFERENCES City (Name, Country, Province),
    CONSTRAINT FK_Airport_Island FOREIGN KEY (Island) REFERENCES Island (Name)
);
